-- composition of rule kernels L:eliminate_duplicated_expr x L:scalar_subquery_to_join (datafusion), template graft_exists
WITH cte1 AS (SELECT 500 AS c0) SELECT FALSE AS c0, a1.c1 AS c1 FROM tp AS a1 WHERE CASE WHEN ((SELECT MAX ('1999-12-31'::date) FROM (SELECT * FROM cte1 WHERE EXISTS (SELECT 1 FROM (SELECT 'c4ca4238a0b923820dcc509a6f75849b'::text AS c0 ORDER BY 1, 1) AS kb) OR NOT EXISTS (SELECT 1 FROM (SELECT 'c4ca4238a0b923820dcc509a6f75849b'::text AS c0 ORDER BY 1, 1) AS kb)) AS a2 WHERE LEAST ((a1.c0 IS NULL), TRUE)) IN (SELECT '1970-01-01'::date AS c0)) THEN FALSE ELSE TRUE END;
-- pgfuzz:check kernel:graft_exists WITH cte1 AS (SELECT 500 AS c0) SELECT FALSE AS c0, a1.c1 AS c1 FROM tp AS a1 WHERE CASE WHEN ((SELECT MAX ('1999-12-31'::date) FROM cte1 AS a2 WHERE LEAST ((a1.c0 IS NULL), TRUE)) IN (SELECT '1970-01-01'::date AS c0)) THEN FALSE ELSE TRUE END
